54	// ─────────────────────────────────────────────────────────────────────────────
55	// Ladebalken (2026-06-01): ASCII-Fortschrittsbalken ueber ALLE kartesischen
56	// Produkte (alle geladenen Plugins, CE + prt-art gemeinsam). Bewusst NUR ASCII
57	// (kein Unicode) wegen NAS/bash + Windows-Konsole. Rendert in-place via '\r' auf
58	// std::cerr; stdout bleibt fuer Mess-/Record-Ausgaben frei. Lange Permutations-IDs
59	// werden gekuerzt, damit die Zeile nicht umbricht; Rest-Zeichen werden geloescht.
60	// ─────────────────────────────────────────────────────────────────────────────
61	class ProgressBar {
62	public:
63	    ProgressBar(std::string_view title, std::size_t total) : title_{title}, total_{total} {
64	        std::cerr << title_ << " (" << total_ << " Permutationen):\n";
65	        render("");
66	    }
67	    void tick(std::string_view label) {
68	        if (cur_ < total_) ++cur_;
69	        render(label);
70	    }
71	    // Meldung oberhalb des Balkens ausgeben, ohne ihn zu zerstoeren.
72	    void note(std::string const& msg) {
73	        std::cerr << '\r' << std::string(line_len_, ' ') << '\r' << msg << '\n';
74	        line_len_ = 0;
75	        render(last_label_);
76	    }
77	    void finish() { std::cerr << '\n'; }
78	
79	private:
80	    void render(std::string_view label) {
81	        last_label_         = std::string{label};
82	        double const frac   = total_ ? static_cast<double>(cur_) / static_cast<double>(total_) : 1.0;
83	        int          filled = static_cast<int>(frac * kWidth);
84	        if (filled > kWidth) filled = kWidth;
85	        std::string bar;
86	        bar.reserve(static_cast<std::size_t>(kWidth));
87	        for (int i = 0; i < kWidth; ++i) bar += (i < filled) ? '=' : ' ';
88	        if (filled > 0 && filled < kWidth) bar[static_cast<std::size_t>(filled) - 1] = '>';
89	        std::string lbl{label};
90	        if (lbl.size() > 48) lbl = lbl.substr(0, 45) + "...";
91	        std::ostringstream os;
92	        os << '\r' << '[' << bar << "] " << cur_ << '/' << total_ << " (" << static_cast<int>(frac * 100.0) << "%) "
93	           << lbl;
94	        std::string out = os.str();
95	        if (out.size() < line_len_) out += std::string(line_len_ - out.size(), ' ');
96	        line_len_ = os.str().size();
97	        std::cerr << out << std::flush;
98	    }
99	    static constexpr int kWidth = 40;
100	    std::string          title_;
101	    std::size_t          total_;
102	    std::size_t          cur_      = 0;
103	    std::size_t          line_len_ = 0;
104	    std::string          last_label_;
105	};
