60	/**
61	 * @brief V32Orchestrator - parallel EE-Submission an CacheEngineBuilder (AA.2)
62	 * @subsystem MessungDriver (Subsystem 1 Outer-Loop)
63	 *
64	 * V33.C.1 Vollausbau:
65	 * - run_default_lookup_messreihe(): konsumiert prt_art DefaultLookupRegistry,
66	 *   iteriert pro Achse die CE-Bibliothek-Variants, fuehrt parallel EE-A + EE-B
67	 *   via std::async, vergleicht via Welch's t-Test.
68	 * - Result-Aggregation in MessreiheReport.
69	 */
70	class V32Orchestrator {
71	public:
72	    V32Orchestrator() = default;
73	
74	    /// V32.GG.1 Skelett-Kompatibilitaet
75	    void submit_to_builder() {
76	        // Im V33.C.1 Vollausbau: ExecuteEngineCommands werden pro Permutation
77	        // direkt im run_default_lookup_messreihe() konstruiert + parallel ausgefuehrt.
78	    }
79	
80	    /// V32.GG.1 Skelett-Kompatibilitaet (existierende Tests)
81	    int execute_messreihe(std::string_view config_xml, std::string_view mode = "defined") {
82	        (void)config_xml;
83	        (void)mode;
84	        return 0;
85	    }
86	
87	    /**
88	     * @brief V33.C.1 Hauptmethode: Default-Lookup-Messreihe ueber alle PRT-ART-Achsen
89	     *
90	     * Workflow:
91	     * 1. Enumerate DefaultLookupRegistry (9 Achsen)
92	     * 2. Pro Achse: AxisLibraryRegistry.lookup() -> Variant-Liste
93	     * 3. Pro Variant: std::async(EE-A) + std::async(EE-B), get() beide
94	     * 4. CompareEngineCommand mit beiden Results
95	     * 5. Outcome in Report sammeln
96	     *
97	     * @param workload Gemeinsamer Workload fuer EE-A + EE-B
98	     * @return MessreiheReport mit kompletter Outcome-Liste + Statistik
99	     */
100	    [[nodiscard]] MessreiheReport run_default_lookup_messreihe(const cmd::Workload& workload) {
101	        MessreiheReport report;
102	        const auto      start = std::chrono::steady_clock::now();
103	
104	        constexpr auto default_axes = dl::DefaultLookupRegistry::enumerate();
105	        report.total_axes           = default_axes.size();
106	
107	        for (const auto& axis : default_axes) {
108	            auto variants = cmd::AxisLibraryRegistry::lookup(std::string(axis.axis_id));
109	            for (const auto& variant : variants) {
110	                ++report.total_variants;
111	                auto outcome = execute_one_permutation(axis.axis_id, variant.variant_name, workload);
112	                switch (outcome.verdict) {
113	                    case cmd::CompareEngineCommand::Verdict::EE_A_Wins: ++report.ee_a_wins; break;
114	                    case cmd::CompareEngineCommand::Verdict::EE_B_Wins: ++report.ee_b_wins; break;
115	                    case cmd::CompareEngineCommand::Verdict::Tie: ++report.ties; break;
116	                    default: break;
117	                }
118	                report.outcomes.push_back(std::move(outcome));
119	            }
120	        }
121	
122	        report.total_elapsed = std::chrono::steady_clock::now() - start;
123	        return report;
124	    }
125	
126	    /**
127	     * @brief V41.P5 (G10): OP-getriebene Messreihe — wirksame op_type → WorkloadKind
128	     *
129	     * Schliesst die vom E2E-Abnahme-Audit gefundene Luecke: vorher war die
130	     * OP-1..OP-6-Empfehlung (datasets §0) NUR dokumentarisch, der op_type wurde
131	     * im Orchestrator ignoriert. Jetzt bildet op_type_filter das XSD-<op_type>-
132	     * Token wirksam auf den WorkloadKind ab, bevor die Messreihe laeuft.
133	     *
134	     * @param op_type_token XSD-Token "OP-1".."OP-6" (messreihe_v32_schema.xsd)
135	     * @param base Basis-Workload (record_count/operation_count/seed bleiben erhalten)
136	     * @param[out] applied true, wenn das Token erkannt + angewandt wurde
137	     * @return MessreiheReport ueber den op_type-spezifischen Workload
138	     */
139	    [[nodiscard]] MessreiheReport run_messreihe_for_op_type(std::string_view op_type_token, const cmd::Workload& base,
140	                                                            bool& applied) {
141	        cmd::Workload effective = base;
142	        applied                 = apply_op_type_token(op_type_token, effective);
143	        return run_default_lookup_messreihe(effective);
144	    }
145	
146	    /// V33.C.1 Einzel-Permutation: parallel EE-A + EE-B + Vergleich
147	    /// V34.A.3 (2026-05-21): nutzt echte Adapter mit as_engine_callable() statt Simulation
148	    [[nodiscard]] PermutationOutcome execute_one_permutation(std::string_view axis_id, std::string_view variant_name,
149	                                                             const cmd::Workload& workload) {
150	        PermutationOutcome outcome;
151	        outcome.axis_id      = std::string(axis_id);
152	        outcome.variant_name = std::string(variant_name);
153	
154	        comdare::cache_engine::abi::CacheEngineExecutionEngineAdapter<> ee_a;
155	        comdare::prt_art::identity::PrtArtExecutionEngineAdapter<>      ee_b;
156	
157	        auto callable_a = ee_a.as_engine_callable();
158	        auto callable_b = ee_b.as_engine_callable();
159	
160	        auto fut_a = std::async(std::launch::async, [&]() {
161	            cmd::ExecuteEngineCommand cmd_a(ee_a.engine_name(), workload, callable_a);
162	            cmd_a.execute();
163	            return cmd_a.result();
164	        });
165	        auto fut_b = std::async(std::launch::async, [&]() {
166	            cmd::ExecuteEngineCommand cmd_b(ee_b.engine_name(), workload, callable_b);
167	            cmd_b.execute();
168	            return cmd_b.result();
169	        });
170	
171	        outcome.ee_a_result = fut_a.get();
172	        outcome.ee_b_result = fut_b.get();
173	
174	        cmd::CompareEngineCommand compare(outcome.ee_a_result, outcome.ee_b_result);
175	        compare.execute();
176	        outcome.verdict          = compare.verdict();
177	        outcome.throughput_ratio = compare.throughput_ratio();
178	        if (compare.welch().valid) { outcome.welch_p_value = compare.welch().p_value; }
179	        return outcome;
180	    }
181	};
