59	inline void plugin_close(PluginHandle h) {
60	    if (!h) return;
61	#if defined(_WIN32)
62	    ::FreeLibrary(h);
63	#else
64	    ::dlclose(h);
65	#endif
66	}
67	
68	inline void* plugin_sym(PluginHandle h, char const* name) {
69	#if defined(_WIN32)
70	    return reinterpret_cast<void*>(::GetProcAddress(h, name));
71	#else
72	    return ::dlsym(h, name);
73	#endif
74	}
75	
76	inline LoadedPlugin load_perm_plugin(std::filesystem::path const& p) {
77	    LoadedPlugin lp;
78	    lp.path   = p;
79	    lp.handle = plugin_open(p);
80	    if (!lp.handle) { return lp; }
81	    using DescFn = const PermDescriptor* (*)();
82	    auto fn      = reinterpret_cast<DescFn>(plugin_sym(lp.handle, "comdare_perm_descriptor"));
83	    if (!fn) {
84	        plugin_close(lp.handle);
85	        lp.handle = nullptr;
86	        return lp;
87	    }
88	    lp.desc = fn();
89	    return lp;
90	}
91	
92	// Scannt rekursiv ein perm-Subsystem-Verzeichnis (cache_engine/ oder prt_art/)
93	// nach .dll/.so/.dylib-Dateien (alle Plugin-Dateien).
94	inline std::vector<std::filesystem::path> discover_plugin_paths(std::filesystem::path const& root) {
95	    std::vector<std::filesystem::path> out;
96	    if (!std::filesystem::exists(root)) { return out; }
97	    namespace fs = std::filesystem;
98	    for (auto& entry : fs::recursive_directory_iterator(root)) {
99	        if (!entry.is_regular_file()) continue;
100	        auto const& path = entry.path();
101	        auto        ext  = path.extension().string();
102	        // Windows: .dll  Linux: .so  macOS: .dylib
103	        if (ext == ".dll" || ext == ".so" || ext == ".dylib") {
104	            // Filter: nur Dateien die mit "perm_" anfangen
105	            auto name = path.stem().string();
106	            if (name.rfind("perm_", 0) == 0) { out.push_back(path); }
107	        }
108	    }
109	    return out;
110	}
111	
112	// Hochlevel-API: laedt alle Plugins beider Wurzeln (cache_engine + prt_art).
113	// perm_root = ${BINARY_DIR}/perm
114	inline std::vector<LoadedPlugin> load_all_perm_plugins(std::filesystem::path const& perm_root) {
115	    std::vector<LoadedPlugin> out;
116	    auto                      ce_paths = discover_plugin_paths(perm_root / "cache_engine");
117	    auto                      pa_paths = discover_plugin_paths(perm_root / "prt_art");
118	    out.reserve(ce_paths.size() + pa_paths.size());
119	    for (auto& p : ce_paths) {
120	        auto lp = load_perm_plugin(p);
121	        if (lp.handle && lp.desc) {
122	            out.push_back(lp);
123	        } else {
124	            std::cerr << "[V38.C] WARN: konnte nicht laden: " << p.string() << "\n";
125	            if (lp.handle) plugin_close(lp.handle);
126	        }
127	    }
128	    for (auto& p : pa_paths) {
129	        auto lp = load_perm_plugin(p);
130	        if (lp.handle && lp.desc) {
131	            out.push_back(lp);
132	        } else {
133	            std::cerr << "[V38.C] WARN: konnte nicht laden: " << p.string() << "\n";
134	            if (lp.handle) plugin_close(lp.handle);
135	        }
136	    }
137	    return out;
138	}
