140	inline void unload_all(std::vector<LoadedPlugin>& plugins) {
141	    for (auto& lp : plugins) {
142	        plugin_close(lp.handle);
143	        lp.handle = nullptr;
144	        lp.desc   = nullptr;
145	    }
146	    plugins.clear();
147	}
