2	// V41.B1 (2026-05-24) - Binary Measurement-Records pro Permutation
3	//
4	// Schreibt binary-File im Format das Stage 03 (binary_to_csv) erwartet:
5	//   uint32 magic = 0xC0FFEE02
6	//   uint32 version = 2   (V41.P1: v2 fuegt workload_used hinzu; v1 = ohne)
7	//   uint64 num_records
8	//   foreach record:
9	//     uint32 perm_id_len + char[perm_id_len]
10	//     uint64 fingerprint
11	//     uint8  succeeded
12	//     [v2+] uint32 workload_len + char[workload_len]   (workload_used, z.B. "micro"/"YCSB_A")
13	//     comdare_measurement_record_v1 (fixed-size POD)
14	
15	#pragma once
16	
17	#include <cache_engine/abi/module_abi_v1.hpp>
18	
19	#include <cstdint>
20	#include <cstring>
21	#include <filesystem>
22	#include <fstream>
23	#include <string>
24	#include <string_view>
25	#include <vector>
26	
27	namespace comdare::messung_driver {
28	
29	inline constexpr std::uint32_t kMeasurementMagic   = 0xC0FFEE02u;
30	inline constexpr std::uint32_t kMeasurementVersion = 2u; // V41.P1: v2 = + workload_used pro Record
31	
32	class MeasurementWriter {
33	public:
34	    explicit MeasurementWriter(std::filesystem::path const& path) : path_{path} {
35	        std::filesystem::create_directories(path.parent_path());
36	        ofs_.open(path, std::ios::binary | std::ios::trunc);
37	        if (!ofs_) { return; }
38	        // Header schreiben (num_records vorerst 0, am Ende ueberschrieben)
39	        ofs_.write(reinterpret_cast<char const*>(&kMeasurementMagic), sizeof(std::uint32_t));
40	        ofs_.write(reinterpret_cast<char const*>(&kMeasurementVersion), sizeof(std::uint32_t));
41	        std::uint64_t zero{0};
42	        ofs_.write(reinterpret_cast<char const*>(&zero), sizeof(std::uint64_t));
43	    }
44	
45	    [[nodiscard]] bool ok() const { return ofs_.is_open() && !ofs_.fail(); }
46	
47	    // V41.P1: workload_used (z.B. "micro" fuer den Plugin-Mikrobench, "YCSB_A".. fuer echte Reihen)
48	    // wird als laengen-praefixierter String VOR dem POD-Record geschrieben (Container-v2).
49	    void add(std::string_view perm_id, std::uint64_t fingerprint, bool succeeded, std::string_view workload_used,
50	             comdare_measurement_record_v1 const& rec) {
51	        if (!ofs_) return;
52	        std::uint32_t const id_len = static_cast<std::uint32_t>(perm_id.size());
53	        ofs_.write(reinterpret_cast<char const*>(&id_len), sizeof(std::uint32_t));
54	        ofs_.write(perm_id.data(), static_cast<std::streamsize>(id_len));
55	        ofs_.write(reinterpret_cast<char const*>(&fingerprint), sizeof(std::uint64_t));
56	        std::uint8_t const succ_byte = succeeded ? 1u : 0u;
57	        ofs_.write(reinterpret_cast<char const*>(&succ_byte), sizeof(std::uint8_t));
58	        std::uint32_t const wl_len = static_cast<std::uint32_t>(workload_used.size());
59	        ofs_.write(reinterpret_cast<char const*>(&wl_len), sizeof(std::uint32_t));
60	        ofs_.write(workload_used.data(), static_cast<std::streamsize>(wl_len));
61	        ofs_.write(reinterpret_cast<char const*>(&rec), sizeof(comdare_measurement_record_v1));
62	        ++num_records_;
63	    }
64	
65	    // Finalisiert die Datei: aktualisiert num_records im Header.
66	    void finalize() {
67	        if (!ofs_) return;
68	        ofs_.flush();
69	        // num_records steht an Offset 8 (nach magic + version)
70	        ofs_.seekp(static_cast<std::streamoff>(2 * sizeof(std::uint32_t)));
71	        ofs_.write(reinterpret_cast<char const*>(&num_records_), sizeof(std::uint64_t));
72	        ofs_.flush();
73	        ofs_.close();
74	    }
75	
76	    ~MeasurementWriter() { finalize(); }
77	
78	    [[nodiscard]] std::uint64_t                count() const { return num_records_; }
79	    [[nodiscard]] std::filesystem::path const& path() const { return path_; }
80	
81	private:
82	    std::filesystem::path path_;
83	    std::ofstream         ofs_;
84	    std::uint64_t         num_records_{0};
85	};
86	
87	// Helper: us/op + Achsen-Info -> measurement_record_v1
88	inline comdare_measurement_record_v1 make_record_from_run(std::uint64_t n_ops, double micros_per_op) {
89	    comdare_measurement_record_v1 r{};
90	    r.version  = kMeasurementVersion;
91	    r.op_count = n_ops;
92	    // total_cycles approximieren aus us/op (1 us ~ 3000 cycles bei 3 GHz)
93	    // (Phase 6+: PerfCounter ablesen statt approximieren)
94	    double total_us           = micros_per_op * static_cast<double>(n_ops);
95	    r.total_cycles            = static_cast<std::uint64_t>(total_us * 3000.0);
96	    r.cache_misses_l1         = 0; // Phase 6+: PMU-Counter
97	    r.cache_misses_l2         = 0;
98	    r.cache_misses_l3         = 0;
99	    r.dtlb_misses             = 0;
100	    r.coherence_invalidations = 0;
101	    r.energy_micro_joules     = 0;
102	    r.bytes_allocated         = n_ops * 64; // Schaetzung: HashSet-Bucket-Size
103	    r.bytes_in_use_peak       = r.bytes_allocated;
104	    r.external_fragmentation  = 0.0;
105	    r.internal_fragmentation  = 0.0;
106	    return r;
107	}
108	
109	// Stable Hash fuer perm_id -> Fingerprint (FNV-1a 64-bit)
110	inline std::uint64_t fingerprint_of(std::string_view s) {
111	    std::uint64_t h = 14695981039346656037ULL;
112	    for (char c : s) {
113	        h ^= static_cast<std::uint64_t>(static_cast<unsigned char>(c));
114	        h *= 1099511628211ULL;
115	    }
116	    return h;
117	}
