30	struct PermStats {
31	    std::string permutation_id;
32	    std::string subsystem;
33	    std::string axes;
34	    std::string version;
35	    std::size_t n_runs{0};
36	    double      mean_us{0.0};
37	    double      stddev{0.0};
38	    double      sem{0.0};     // standard error of mean = stddev/sqrt(n)
39	    double      ci_low{0.0};  // 95%-CI lower
40	    double      ci_high{0.0}; // 95%-CI upper
41	    double      min_us{0.0};
42	    double      max_us{0.0};
43	};
44	
45	// Student-t (zweiseitiges 95%-Quantil) approximiert per Welch-Satterthwaite-
46	// Inversion ueber den welch_t_test-Code: hier hartcodierte t_{0.025,df} fuer
47	// kleine N (Tabelle), Fallback ~1.96 fuer grosses N.
48	inline double t_critical_95(std::size_t n) {
49	    if (n < 2) return 0.0;
50	    // Quantile df -> t_{0.025, df}
51	    static constexpr struct {
52	        std::size_t df;
53	        double      t;
54	    } kTable[] = {
55	        {1, 12.706}, {2, 4.303},  {3, 3.182},   {4, 2.776},   {5, 2.571},   {6, 2.447},
56	        {7, 2.365},  {8, 2.306},  {9, 2.262},   {10, 2.228},  {15, 2.131},  {20, 2.086},
57	        {30, 2.042}, {50, 2.009}, {100, 1.984}, {200, 1.972}, {500, 1.965}, {1000, 1.962},
58	    };
59	    std::size_t df = n - 1;
60	    for (auto const& e : kTable) {
61	        if (df <= e.df) return e.t;
62	    }
63	    return 1.96;
64	}
65	
66	[[nodiscard]] inline PermStats compute_stats(std::string_view perm_id, std::string_view subsystem,
67	                                             std::string_view axes, std::string_view version,
68	                                             std::span<const double> samples_us) {
69	    PermStats s{};
70	    s.permutation_id = perm_id;
71	    s.subsystem      = subsystem;
72	    s.axes           = axes;
73	    s.version        = version;
74	    s.n_runs         = samples_us.size();
75	    if (samples_us.empty()) return s;
76	
77	    double sum = std::accumulate(samples_us.begin(), samples_us.end(), 0.0);
78	    s.mean_us  = sum / static_cast<double>(s.n_runs);
79	
80	    double sq = 0.0;
81	    for (double v : samples_us) {
82	        double d = v - s.mean_us;
83	        sq += d * d;
84	    }
85	    if (s.n_runs >= 2) {
86	        double var = sq / static_cast<double>(s.n_runs - 1);
87	        s.stddev   = std::sqrt(var);
88	        s.sem      = s.stddev / std::sqrt(static_cast<double>(s.n_runs));
89	        double t   = t_critical_95(s.n_runs);
90	        s.ci_low   = s.mean_us - t * s.sem;
91	        s.ci_high  = s.mean_us + t * s.sem;
92	    } else {
93	        s.ci_low  = s.mean_us;
94	        s.ci_high = s.mean_us;
95	    }
96	    auto [mn, mx] = std::minmax_element(samples_us.begin(), samples_us.end());
97	    s.min_us      = *mn;
98	    s.max_us      = *mx;
99	    return s;
100	}
101	
102	// Welch's t-test ueber Mikrosekunden-Samples (cache-engine erwartet int64).
103	// Konvertiere us -> ns int64 fuer numerische Stabilitaet.
104	inline cache_engine::builder::commands::stats::WelchResult welch_us(std::span<const double> a_us,
105	                                                                    std::span<const double> b_us) {
106	    std::vector<std::int64_t> a_ns, b_ns;
107	    a_ns.reserve(a_us.size());
108	    b_ns.reserve(b_us.size());
109	    for (double v : a_us) a_ns.push_back(static_cast<std::int64_t>(v * 1000.0));
110	    for (double v : b_us) b_ns.push_back(static_cast<std::int64_t>(v * 1000.0));
111	    return cache_engine::builder::commands::stats::welch_t_test(std::span<const std::int64_t>(a_ns),
112	                                                                std::span<const std::int64_t>(b_ns));
113	}
