1	#pragma once
2	// V33.D.2 (2026-05-21) - MessreiheV32Validator: Code-side XML-Schema-Validation
3	//
4	// @subsystem MessungDriver
5	// @phase_owner MessungDriver
6	//
7	// Validiert messreihe_v32_*.xml gegen das informelle Schema in
8	// test_data_xml/messreihe_v32_schema.xsd. Kein externer XML-Parser noetig —
9	// nutzt nur std::string Find-Operations + Struktur-Pruefungen.
10	//
11	// Header-only, keine Dependencies. Wenn spaeter pugixml/tinyxml2 verfuegbar
12	// ist, kann der Validator gegen vollstaendige XSD-Validation getauscht werden.
13	
14	#include <algorithm>
15	#include <fstream>
16	#include <sstream>
17	#include <string>
18	#include <string_view>
19	#include <vector>
20	
21	namespace comdare::diplomarbeit::messung_driver::v32 {
22	
23	struct ValidationIssue {
24	    enum class Severity { Error, Warning };
25	    Severity    severity{Severity::Error};
26	    std::string message;
27	};
28	
29	struct ValidationReport {
30	    std::vector<ValidationIssue> issues;
31	    bool                         valid{false};
32	
33	    [[nodiscard]] bool has_errors() const noexcept {
34	        for (const auto& i : issues) {
35	            if (i.severity == ValidationIssue::Severity::Error) return true;
36	        }
37	        return false;
38	    }
39	    [[nodiscard]] std::size_t error_count() const noexcept {
40	        return std::ranges::count_if(issues,
41	                                     [](const auto& i) { return i.severity == ValidationIssue::Severity::Error; });
42	    }
43	};
44	
45	class MessreiheV32Validator {
46	public:
47	    [[nodiscard]] static ValidationReport validate_string(std::string_view xml) {
48	        ValidationReport report;
49	
50	        // Pflicht: XML-Header
51	        if (xml.find("<?xml") == std::string_view::npos) { add_error(report, "Missing <?xml declaration"); }
52	
53	        // Pflicht: <messreihe version="32"> Root-Element
54	        if (xml.find("<messreihe") == std::string_view::npos) {
55	            add_error(report, "Missing root element <messreihe>");
56	        } else if (xml.find("version=\"32\"") == std::string_view::npos) {
57	            add_error(report, "Root <messreihe> must have version=\"32\"");
58	        }
59	
60	        // Pflicht: <metadata> mit <mode>
61	        require_element(report, xml, "<metadata>", "metadata block");
62	        require_element(report, xml, "<name>", "metadata/name");
63	        require_element(report, xml, "<mode>", "metadata/mode");
64	        if (xml.find("<mode>defined</mode>") == std::string_view::npos &&
65	            xml.find("<mode>full</mode>") == std::string_view::npos &&
66	            xml.find("<mode>full_sampled</mode>") == std::string_view::npos) {
67	            add_error(report, "metadata/mode must be 'defined', 'full', or 'full_sampled'");
68	        }
69	
70	        // Pflicht: <execution_engines> mit GENAU 2 <engine>
71	        require_element(report, xml, "<execution_engines>", "execution_engines block");
72	        const auto engine_count = count_occurrences(xml, "<engine ");
73	        if (engine_count != 2) {
74	            add_error(report,
75	                      "execution_engines must contain exactly 2 <engine>, found " + std::to_string(engine_count));
76	        }
77	
78	        // Pflicht: mindestens 1 <tupel>
79	        const auto tupel_count = count_occurrences(xml, "<tupel ");
80	        if (tupel_count == 0) { add_error(report, "At least one <tupel> required"); }
81	        // Pro tupel: <workload>
82	        const auto workload_count = count_occurrences(xml, "<workload ");
83	        if (workload_count < tupel_count) {
84	            add_error(report, "Every <tupel> needs a <workload>, found " + std::to_string(workload_count) +
85	                                  " workloads for " + std::to_string(tupel_count) + " tupels");
86	        }
87	
88	        // Pflicht: <output> mit Pfaden
89	        require_element(report, xml, "<output>", "output block");
90	        require_element(report, xml, "<binary_path>", "output/binary_path");
91	        require_element(report, xml, "<csv_path>", "output/csv_path");
92	        require_element(report, xml, "<latex_path>", "output/latex_path");
93	
94	        // Optional: <axes_default_lookup enabled="...">
95	        if (xml.find("<axes_default_lookup") != std::string_view::npos &&
96	            xml.find("enabled=\"") == std::string_view::npos) {
97	            add_warning(report, "axes_default_lookup present but enabled-attribute missing");
98	        }
99	
100	        // Closing tag
101	        if (xml.find("</messreihe>") == std::string_view::npos) { add_error(report, "Missing closing </messreihe>"); }
102	
103	        report.valid = !report.has_errors();
104	        return report;
105	    }
106	
107	    [[nodiscard]] static ValidationReport validate_file(std::string_view path) {
108	        std::ifstream f{std::string(path)};
109	        if (!f.is_open()) {
110	            ValidationReport report;
111	            add_error(report, "Cannot open XML file: " + std::string(path));
112	            return report;
113	        }
114	        std::stringstream ss;
115	        ss << f.rdbuf();
116	        return validate_string(ss.str());
117	    }
118	
119	private:
120	    static void add_error(ValidationReport& report, const std::string& msg) {
121	        report.issues.push_back({ValidationIssue::Severity::Error, msg});
122	    }
123	    static void add_warning(ValidationReport& report, const std::string& msg) {
124	        report.issues.push_back({ValidationIssue::Severity::Warning, msg});
125	    }
126	    static void require_element(ValidationReport& report, std::string_view xml, std::string_view needle,
127	                                std::string_view human) {
128	        if (xml.find(needle) == std::string_view::npos) {
129	            add_error(report, "Missing " + std::string(human) + " (needle: " + std::string(needle) + ")");
130	        }
131	    }
132	    static std::size_t count_occurrences(std::string_view haystack, std::string_view needle) {
133	        if (needle.empty()) return 0;
134	        std::size_t count = 0;
135	        std::size_t pos   = 0;
136	        while ((pos = haystack.find(needle, pos)) != std::string_view::npos) {
137	            ++count;
138	            pos += needle.size();
139	        }
140	        return count;
141	    }
142	};
143	
