2	// V33.E.4 (2026-05-21) - HardwareFilter: Tupel-Filter gegen Host-Capabilities
3	//
4	// @subsystem MessungDriver
5	// @phase_owner MessungDriver
6	//
7	// Q.1-Akzeptanz-Kriterium: messung_driver filtert Datasets gegen verfuegbare Hardware.
8	//
9	// Wenn ein Tupel <hardware_strategy><simd>AVX512</simd></hardware_strategy> verlangt,
10	// aber der Host nur AVX2 unterstuetzt, wird der Tupel uebersprungen.
11	//
12	// Header-only, keine Dependencies. Echte IPlatformProbe-Verdrahtung folgt V34+.
13	
14	#include <algorithm>
15	#include <array>
16	#include <string>
17	#include <string_view>
18	#include <vector>
19	
20	namespace comdare::diplomarbeit::messung_driver::v32 {
21	
22	/// V35.B.2 — Compiler-Family (Achse 15.1)
23	enum class CompilerFamily { Unknown, GCC, Clang, AppleClang, MSVC };
24	
25	/**
26	 * @brief HostCapabilities - Auswahl an Hardware-Faehigkeiten des Hosts
27	 * @subsystem MessungDriver
28	 *
29	 * Wird typischerweise via IPlatformProbe ermittelt (cache-engine V31).
30	 * Hier vereinfacht als Compile-time bzw. constructor-init Wert.
31	 */
32	struct HostCapabilities {
33	    bool        supports_avx2{false};
34	    bool        supports_avx512{false};
35	    bool        supports_neon{false};
36	    bool        supports_sve2{false};
37	    bool        numa_available{false};
38	    bool        huge_pages_2mb{false};
39	    bool        huge_pages_1gb{false};
40	    std::size_t num_p_cores{0};
41	    std::size_t num_e_cores{0};
42	
43	    /// V35.B.2 — Compiler-Family (Achse 15.1) erfasst beim Build dieses Binaries
44	    CompilerFamily compiler_family{CompilerFamily::Unknown};
45	
46	    /// Default-Konstruktor mit konservativen Annahmen (alles false ausser scalar)
47	    constexpr HostCapabilities() noexcept = default;
48	
49	    /// Compile-time bekannte Capabilities (z.B. via Build-Flags injiziert)
50	    static HostCapabilities detect_compile_time() noexcept {
51	        HostCapabilities hc;
52	#if defined(__AVX2__)
53	        hc.supports_avx2 = true;
54	#endif
55	#if defined(__AVX512F__)
56	        hc.supports_avx512 = true;
57	#endif
58	#if defined(__ARM_NEON)
59	        hc.supports_neon = true;
60	#endif
61	#if defined(__ARM_FEATURE_SVE2)
62	        hc.supports_sve2 = true;
63	#endif
64	        // V35.B.2 — Compiler-Detection
65	#if defined(__clang__) && defined(__APPLE_CC__)
66	        hc.compiler_family = CompilerFamily::AppleClang;
67	#elif defined(__clang__)
68	        hc.compiler_family = CompilerFamily::Clang;
69	#elif defined(__GNUC__)
70	        hc.compiler_family = CompilerFamily::GCC;
71	#elif defined(_MSC_VER)
72	        hc.compiler_family = CompilerFamily::MSVC;
73	#endif
74	        return hc;
75	    }
76	};
77	
78	/// V35.B.2 — Compiler-Family string conversion
79	[[nodiscard]] inline std::string_view compiler_family_name(CompilerFamily f) noexcept {
80	    switch (f) {
81	        case CompilerFamily::GCC: return "GCC";
82	        case CompilerFamily::Clang: return "Clang";
83	        case CompilerFamily::AppleClang: return "AppleClang";
84	        case CompilerFamily::MSVC: return "MSVC";
85	        case CompilerFamily::Unknown: return "Unknown";
86	    }
87	    return "Unknown";
88	}
89	
90	/**
91	 * @brief HardwareRequest - Hardware-Strategie aus messreihen.xml `<hardware_strategy>`
92	 * @subsystem MessungDriver
93	 */
94	struct HardwareRequest {
95	    std::string simd;               ///< z.B. "AVX2", "AVX512", "Scalar", "NEON", "SVE2"
96	    std::string cache_level;        ///< z.B. "L1Aware", "L2Aware", "L3Aware", "HBMAware"
97	    std::string numa;               ///< z.B. "Local", "Interleave", "Preferred", "Bind"
98	    std::string prefetch_distance;  ///< z.B. "PrefetchT0", "PrefetchT1", "PrefetchNTA"
99	    std::string atomic_granularity; ///< z.B. "CAS_64", "CAS_128", "LL_SC"
100	
101	    [[nodiscard]] bool empty() const noexcept {
102	        return simd.empty() && cache_level.empty() && numa.empty() && prefetch_distance.empty() &&
103	               atomic_granularity.empty();
104	    }
105	};
106	
107	/**
108	 * @brief CompilerRequest - Compiler-Strategie aus messreihen.xml `<compiler_strategy>` (V35.B)
109	 * @subsystem MessungDriver
110	 *
111	 * Achse 15: 15.1 family, 15.2 opt_level, 15.3 lto, 15.4 pgo, 15.5 target_arch.
112	 */
113	struct CompilerRequest {
114	    std::string family;      ///< "GCC", "Clang", "AppleClang", "MSVC"
115	    std::string opt_level;   ///< "O0".."O3", "Ofast", "MSVC_Od", "MSVC_O1", "MSVC_O2"
116	    std::string lto;         ///< "None", "ThinLTO", "FullLTO", "MSVC_LTCG"
117	    std::string pgo;         ///< "None", "Generate", "Use", "SamplePGO"
118	    std::string target_arch; ///< "native", "x86-64-v3", "x86-64-v4", "znver4", "armv9-a", "generic"
119	
120	    [[nodiscard]] bool empty() const noexcept {
121	        return family.empty() && opt_level.empty() && lto.empty() && pgo.empty() && target_arch.empty();
122	    }
123	};
124	
125	/**
126	 * @brief FilterDecision - Ergebnis des HardwareFilter
127	 * @subsystem MessungDriver
128	 */
129	struct FilterDecision {
130	    enum class Verdict { Pass, Skip };
131	    Verdict            verdict{Verdict::Pass};
132	    std::string        reason; ///< Begruendung wenn Skip
133	    [[nodiscard]] bool passes() const noexcept { return verdict == Verdict::Pass; }
134	};
135	
136	/**
137	 * @brief HardwareFilter - Pruefe Tupel gegen Host-Capabilities
138	 * @subsystem MessungDriver
139	 *
140	 * Akzeptiert Tupel wenn Host die geforderte SIMD-Family unterstuetzt.
141	 * Empty HardwareRequest -> immer pass.
142	 */
143	class HardwareFilter {
144	public:
145	    explicit HardwareFilter(HostCapabilities host) noexcept : host_{host} {}
146	
147	    [[nodiscard]] FilterDecision evaluate(const HardwareRequest& req) const {
148	        if (req.empty()) { return {FilterDecision::Verdict::Pass, "no hardware constraints"}; }
149	
150	        if (!req.simd.empty()) {
151	            if (req.simd == "AVX2" && !host_.supports_avx2) {
152	                return {FilterDecision::Verdict::Skip, "AVX2 required but host lacks it"};
153	            }
154	            if (req.simd == "AVX512" && !host_.supports_avx512) {
155	                return {FilterDecision::Verdict::Skip, "AVX512 required but host lacks it"};
156	            }
157	            if (req.simd == "NEON" && !host_.supports_neon) {
158	                return {FilterDecision::Verdict::Skip, "NEON required but host lacks it"};
159	            }
160	            if (req.simd == "SVE2" && !host_.supports_sve2) {
161	                return {FilterDecision::Verdict::Skip, "SVE2 required but host lacks it"};
162	            }
163	            // Scalar ist immer verfuegbar.
164	        }
165	
166	        if (!req.numa.empty() && req.numa != "Local" && !host_.numa_available) {
167	            return {FilterDecision::Verdict::Skip, "NUMA strategy '" + req.numa + "' requires NUMA support"};
168	        }
169	
170	        // Cache-Level + Prefetch + Atomic-Granularity sind Soft-Constraints (kein Skip)
171	        return {FilterDecision::Verdict::Pass, "all constraints satisfied"};
172	    }
173	
174	    /// V35.B.3 — Compiler-Filter (Achse 15.1 family + 15.5 target_arch)
175	    /// Soft-Filter: prueft nur ob die geforderte Family auf dem Host verfuegbar ist.
176	    /// LTO/PGO/OptLevel sind reine Compile-Time-Konfigurationen und werden hier nicht gefiltert.
177	    [[nodiscard]] FilterDecision evaluate(const CompilerRequest& req) const {
178	        if (req.empty()) { return {FilterDecision::Verdict::Pass, "no compiler constraints"}; }
179	        if (!req.family.empty()) {
180	            const auto host_family_name = compiler_family_name(host_.compiler_family);
181	            if (req.family != host_family_name) {
182	                return {FilterDecision::Verdict::Skip, "compiler '" + req.family + "' requested but host built with '" +
183	                                                           std::string(host_family_name) + "'"};
184	            }
185	        }
186	        if (req.target_arch == "armv9-a" && !host_.supports_neon) {
187	            return {FilterDecision::Verdict::Skip,
188	                    "target_arch 'armv9-a' requires ARM host but x86-Detection fehlt NEON"};
189	        }
190	        if (req.target_arch == "x86-64-v4" && !host_.supports_avx512) {
191	            return {FilterDecision::Verdict::Skip, "target_arch 'x86-64-v4' requires AVX-512"};
192	        }
193	        // OptLevel / LTO / PGO sind Compile-Time-only -> kein Skip
194	        return {FilterDecision::Verdict::Pass, "compiler constraints satisfied"};
195	    }
196	
197	    [[nodiscard]] const HostCapabilities& host() const noexcept { return host_; }
198	
199	private:
200	    HostCapabilities host_;
201	};
202	
203	} // namespace comdare::diplomarbeit::messung_driver::v32
