2	// V36.D (2026-05-23) - Runtime-Check fuer Pre-Build-Permutationen
3	//
4	// User-Direktive Sonderfall: "Keine Prebuilds vorhanden und bauen ist aus,
5	// dann Error: Kein Experiment möglich"
6	//
7	// Triggert FATAL wenn beide Manifeste leer/missing — dann hat kein Experiment
8	// einen Sinn, weil keine Permutationen zum durchlaufen verfuegbar sind.
9	
10	#pragma once
11	
12	#include <cstdint>
13	#include <filesystem>
14	#include <fstream>
15	#include <iostream>
16	#include <string>
17	#include <vector>
18	
19	#ifndef COMDARE_PERMUTATIONS_MANIFEST_CE
20	#define COMDARE_PERMUTATIONS_MANIFEST_CE ""
21	#endif
22	#ifndef COMDARE_PERMUTATIONS_MANIFEST_PA
23	#define COMDARE_PERMUTATIONS_MANIFEST_PA ""
24	#endif
25	
26	namespace comdare::messung_driver {
27	
28	struct PermutationsAvailability {
29	    std::size_t cache_engine_count{0};
30	    std::size_t prt_art_count{0};
31	    bool        ce_manifest_found{false};
32	    bool        pa_manifest_found{false};
33	};
34	
35	inline std::size_t count_manifest_entries(std::filesystem::path const& p) {
36	    if (!std::filesystem::exists(p)) { return 0; }
37	    std::ifstream in(p);
38	    if (!in) { return 0; }
39	    std::size_t count{0};
40	    for (std::string line; std::getline(in, line);) {
41	        if (line.empty() || line.front() == '#') { continue; }
42	        ++count;
43	    }
44	    return count;
45	}
46	
47	inline PermutationsAvailability probe_permutations() {
48	    PermutationsAvailability a;
49	    std::filesystem::path    ce{COMDARE_PERMUTATIONS_MANIFEST_CE};
50	    std::filesystem::path    pa{COMDARE_PERMUTATIONS_MANIFEST_PA};
51	    a.ce_manifest_found  = std::filesystem::exists(ce);
52	    a.pa_manifest_found  = std::filesystem::exists(pa);
53	    a.cache_engine_count = count_manifest_entries(ce);
54	    a.prt_art_count      = count_manifest_entries(pa);
55	    return a;
56	}
57	
58	// V37.C (2026-05-23): Manifest-Lader fuer Iteration ueber Permutationen
59	inline std::vector<std::string> load_manifest_entries(std::filesystem::path const& p) {
60	    std::vector<std::string> out;
61	    if (!std::filesystem::exists(p)) { return out; }
62	    std::ifstream in(p);
63	    for (std::string line; std::getline(in, line);) {
64	        if (line.empty() || line.front() == '#') { continue; }
65	        // trim CR (Windows line-endings)
66	        if (!line.empty() && line.back() == '\r') { line.pop_back(); }
67	        out.push_back(std::move(line));
68	    }
69	    return out;
70	}
71	
72	struct PermutationEntry {
73	    std::string id;
74	    std::string subsystem; // "cache_engine" | "prt_art"
75	};
76	
77	inline std::vector<PermutationEntry> load_all_permutations() {
78	    std::vector<PermutationEntry> out;
79	    for (auto const& id : load_manifest_entries(COMDARE_PERMUTATIONS_MANIFEST_CE)) {
80	        out.push_back({id, "cache_engine"});
81	    }
82	    for (auto const& id : load_manifest_entries(COMDARE_PERMUTATIONS_MANIFEST_PA)) { out.push_back({id, "prt_art"}); }
83	    return out;
84	}
85	
86	// Return: 0 = ok, 2 = no permutations available (fatal)
87	[[nodiscard]] inline int assert_permutations_available_or_die() {
88	    auto a = probe_permutations();
89	    if (a.cache_engine_count == 0 && a.prt_art_count == 0) {
90	        std::cerr << "FATAL [V36.D]: Kein Experiment moeglich.\n"
91	                  << "  cache-engine Permutationen: " << a.cache_engine_count
92	                  << " (manifest=" << COMDARE_PERMUTATIONS_MANIFEST_CE << ", found=" << a.ce_manifest_found << ")\n"
93	                  << "  prt-art Pruefling-Permutationen: " << a.prt_art_count
94	                  << " (manifest=" << COMDARE_PERMUTATIONS_MANIFEST_PA << ", found=" << a.pa_manifest_found << ")\n"
95	                  << "  Loesung: cmake -DCOMDARE_PERMUTATION_MODE=on_build_on_demand "
96	                  << "und cmake --build <preset> --target comdare_perms_all\n";
97	        return 2;
98	    }
99	    std::cout << "[V36.D] Permutationen: cache-engine=" << a.cache_engine_count << "  prt-art=" << a.prt_art_count
100	              << "\n";
101	    return 0;
102	}
103	
104	} // namespace comdare::messung_driver
