91	// Phase 1: ENUMERATION (XML-Parsing + Permutations-Enumeration)
92	// ─────────────────────────────────────────────────────────────────────────────
93	int ExperimentDriver::phase1_enumerate(std::vector<loop::PermutationDescriptor>& out_descriptors) {
94	    try {
95	        // INV-4/kein-Silent-Skip (Fix 2026-07-06): fehlendes Config-Verzeichnis ist ein FEHLER,
96	        // kein leerer Erfolg (parse_one liefert sonst still {} je Datei -> 0 Permutationen "ok").
97	        if (!std::filesystem::is_directory(opts_.config_dir)) {
98	            std::cerr << "[Phase 1] Config-Verzeichnis fehlt: " << opts_.config_dir.string() << "\n";
99	            return status_xml_parse_failed;
100	        }
101	        xml::XmlConfigParser parser;
102	        auto                 cfg = parser.parse(opts_.config_dir);
103	
104	        if (opts_.verbose) {
105	            std::cout << "\n[Phase 1] Parsed XML configs:\n";
106	            std::cout << "  cache_engine_permutations:     " << cfg.cache_engine_permutations.size() << "\n";
107	            std::cout << "  search_algorithm_permutations: " << cfg.search_algorithm_permutations.size() << "\n";
108	            std::cout << "  allocator_permutations:        " << cfg.allocator_permutations.size() << "\n";
109	            std::cout << "  test_data_sets:                " << cfg.test_data_sets.size() << "\n";
110	        }
111	
112	        loop::PermutationLoop pl;
113	        std::size_t const     full_population = cfg.cache_engine_permutations.size() *
114	                                                cfg.search_algorithm_permutations.size() *
115	                                                cfg.allocator_permutations.size() * cfg.test_data_sets.size();
116	        std::uint32_t const   sample_rate =
117	            (opts_.messreihen_mode == ExperimentDriverOptions::MessreihenMode::FullSampled) ? opts_.sample_rate : 0u;
118	        out_descriptors = pl.enumerate(cfg, sample_rate, opts_.sample_seed);
119	
120	        if (opts_.verbose) {
121	            std::cout << "  Enumerated " << out_descriptors.size() << " permutations";
122	            if (sample_rate >= loop::sampling_min_filtered_rate) {
123	                std::cout << " (FullSampled 1:" << sample_rate << ", seed=" << opts_.sample_seed << ")";
124	            }
125	            std::cout << ".\n";
126	        }
127	        if (sample_rate >= loop::sampling_min_filtered_rate && out_descriptors.empty()) {
128	            std::cerr << "[Phase 1] WARN: FullSampled 1:" << sample_rate
129	                      << " ergab 0 Kandidaten (Population=" << full_population
130	                      << "); kleinere --sample-rate waehlen.\n";
131	        }
132	    } catch (std::exception const& e) {
133	        std::cerr << "[Phase 1] XML-Parse error: " << e.what() << "\n";
134	        return status_xml_parse_failed;
135	    }
136	    return status_ok;
137	}
