244	int hot_compile_missing_modules(std::filesystem::path const& generated_dir, std::filesystem::path const& build_dir,
245	                                std::vector<std::uint64_t> const& fingerprints, bool verbose) {
246	    int        hot_compiled  = 0;
247	    auto const dll_dir_debug = build_dir / "Debug";
248	    auto const dll_dir       = std::filesystem::is_directory(dll_dir_debug) ? dll_dir_debug : build_dir;
249	    for (auto fp : fingerprints) {
250	        if (module_binary_exists(dll_dir, fp)) continue;
251	        std::ostringstream target;
252	        target << "comdare_perm_" << std::hex << fp;
253	        std::ostringstream cmd;
254	        cmd << "cmake --build \"" << build_dir.string() << "\" --target " << target.str();
255	        if (verbose) { std::cout << "    [V13.2 hot-compile] " << cmd.str() << "\n"; }
256	        int rc = std::system(cmd.str().c_str());
257	        if (rc == 0) ++hot_compiled;
258	    }
259	    return hot_compiled;
260	}
