297	// REV 7.6 V13.3 — ABI-Vertrags-Pruefung pro geladenem Modul
298	// (no-op wenn enable_functional_tests=false). Prueft fuer jeden Handle:
299	//   - create_instance(nullptr) liefert non-null
300	//   - run_workload mit empty WorkloadDescriptor schreibt rec.version == ABI_VERSION
301	//   - destroy_instance ist sicher aufrufbar
302	int ExperimentDriver::phase4b_functional_tests(std::span<loader::ModuleHandle> handles) {
303	    if (!opts_.enable_functional_tests) return status_ok;
304	    if (opts_.verbose) {
305	        std::cout << "\n[Phase 4b V13.3] Functional-Test ABI-Vertraege fuer " << handles.size() << " Module ...\n";
306	    }
307	    int                            passed = 0;
308	    int                            failed = 0;
309	    comdare_workload_descriptor_v1 empty_workload{};
310	    for (auto& h : handles) {
311	        auto const* m = h.get();
312	        if (!m) {
313	            ++failed;
314	            continue;
315	        }
316	        void* inst = m->create_instance(nullptr);
317	        if (!inst) {
318	            ++failed;
319	            continue;
320	        }
321	        comdare_measurement_record_v1 rec{};
322	        m->run_workload(inst, &empty_workload, &rec);
323	        bool const abi_ok = (rec.version == COMDARE_ABI_VERSION);
324	        m->destroy_instance(inst);
325	        if (abi_ok)
326	            ++passed;
327	        else
328	            ++failed;
329	    }
330	    if (opts_.verbose) {
331	        std::cout << "[Phase 4b V13.3] Functional-Tests: " << passed << " passed / " << failed << " failed\n";
332	    }
333	    return failed > 0 ? status_workload_failed : status_ok;
334	}
