382	// ─────────────────────────────────────────────────────────────────────────────
383	// Phase 5 + 6: EXECUTE + MEASURE (pro Modul: create_instance + run_workload +
384	//                                 destroy_instance; sammle in Aggregator)
385	// ─────────────────────────────────────────────────────────────────────────────
386	int ExperimentDriver::phase5_run_workload(std::span<loader::ModuleHandle> handles, WorkloadOptions const& wopts,
387	                                          std::vector<loop::PermutationDescriptor> const& descriptors,
388	                                          experiment::ResultAggregator&                   aggregator) {
389	    workload_generator::WorkloadGenerator gen{wopts.config};
390	    auto                                  default_ops          = gen.generate_ycsb(wopts.workload);
391	    auto                                  default_workload_abi = gen.to_abi_descriptor(default_ops);
392	
393	    if (opts_.verbose) {
394	        std::cout << "\n[Phase 5+6] Running workload (default: " << default_ops.size() << " ops) against "
395	                  << handles.size() << " modules ...\n";
396	    }
397	
398	    std::unordered_map<std::uint64_t, std::string> fp_to_id;
399	    for (auto const& d : descriptors) fp_to_id[d.fingerprint] = d.id;
400	
401	    // REV 7.6 V11.2 — Profile-aware Workload-Routing
402	    // Pro Profil-Modul wird der Workload aus dem Traversal-Tag des Profils
403	    // abgeleitet. Mapping (traversal -> YCSB-Workload):
404	    //   RANGE_SCAN / RANGE_HOT_PATH    -> YCSB-E (range queries)
405	    //   HOT_PATH / PRTART_HOT_PATH      -> YCSB-A (50/50 read/update Zipfian)
406	    //   STANDARD (default)               -> YCSB-C (read-only)
407	    // Fallback fuer Nicht-Profil-Module: WorkloadOptions::workload (wopts)
408	    auto pick_workload_for_traversal = [](std::string const& traversal) {
409	        if (traversal.find("RANGE") != std::string::npos) return workload_generator::YcsbWorkload::E;
410	        if (traversal.find("HOT_PATH") != std::string::npos) return workload_generator::YcsbWorkload::A;
411	        return workload_generator::YcsbWorkload::C;
412	    };
413	
414	    // V19.3 — expected_workload Tag ueberschreibt traversal-Heuristik
415	    // Mapping (XML-String -> YcsbWorkload): YCSB_A..F
416	    auto parse_expected_workload = [](std::string const& tag) -> workload_generator::YcsbWorkload {
417	        if (tag == "YCSB_A") return workload_generator::YcsbWorkload::A;
418	        if (tag == "YCSB_B") return workload_generator::YcsbWorkload::B;
419	        if (tag == "YCSB_C") return workload_generator::YcsbWorkload::C;
420	        if (tag == "YCSB_D") return workload_generator::YcsbWorkload::D;
421	        if (tag == "YCSB_E") return workload_generator::YcsbWorkload::E;
422	        if (tag == "YCSB_F") return workload_generator::YcsbWorkload::F;
423	        return workload_generator::YcsbWorkload::C; // Fallback
424	    };
425	
426	    // V20.2 — YcsbWorkload -> Export-String (fuer PermutationResult.workload_used)
427	    auto workload_to_string = [](workload_generator::YcsbWorkload w) -> std::string {
428	        using W = workload_generator::YcsbWorkload;
429	        switch (w) {
430	            case W::A: return "YCSB_A";
431	            case W::B: return "YCSB_B";
432	            case W::C: return "YCSB_C";
433	            case W::D: return "YCSB_D";
434	            case W::E: return "YCSB_E";
435	            case W::F: return "YCSB_F";
436	        }
437	        return "UNKNOWN";
438	    };
439	
440	    // Pre-Compute alle Profile-Workload-Mappings (deterministic Fingerprint -> Workload)
441	    std::unordered_map<std::uint64_t, workload_generator::YcsbWorkload> fp_to_workload;
442	    // #193-A: identische robuste Aufloesung wie in Phase 2 (s. resolve_sota_profiles_dir).
443	    auto profiles_dir = resolve_sota_profiles_dir(opts_.config_dir, opts_.comdare_root);
444	    if (std::filesystem::is_directory(profiles_dir)) {
445	        xml::XmlConfigParser parser;
446	        auto                 profiles = parser.load_sota_profiles(profiles_dir);
447	        for (auto const& p : profiles) {
448	            std::uint64_t fp = std::hash<std::string>{}(p.id) ^ 0xC0FFEE02ull;
449	            // V19.3 — Profile-Override: expected_workload > traversal-Heuristik
450	            if (!p.expected_workload.empty()) {
451	                fp_to_workload[fp] = parse_expected_workload(p.expected_workload);
452	                if (opts_.verbose) {
453	                    std::cout << "    [V19.3] Profile " << p.id << " expected_workload=" << p.expected_workload
454	                              << " (Override traversal-Heuristik)\n";
455	                }
456	            } else {
457	                auto        it        = p.axes.find("traversal");
458	                std::string traversal = (it != p.axes.end()) ? it->second : "STANDARD";
459	                fp_to_workload[fp]    = pick_workload_for_traversal(traversal);
460	            }
461	        }
462	    }
463	
464	    std::uint64_t total_records = 0;
465	    for (auto& h : handles) {
466	        auto const* m = h.get();
467	        if (!m) continue;
468	        void* inst = m->create_instance(nullptr);
469	        if (!inst) continue;
470	
471	        // V11.2 — wenn Modul aus Profil stammt, eigenen Workload bauen
472	        auto                                       wl_it              = fp_to_workload.find(h.fingerprint());
473	        comdare_workload_descriptor_v1 const*      wl_for_this_module = &default_workload_abi;
474	        std::vector<workload_generator::Operation> profile_ops;
475	        comdare_workload_descriptor_v1             profile_workload_abi{};
476	        if (wl_it != fp_to_workload.end()) {
477	            profile_ops          = gen.generate_ycsb(wl_it->second);
478	            profile_workload_abi = gen.to_abi_descriptor(profile_ops);
479	            wl_for_this_module   = &profile_workload_abi;
480	            if (opts_.verbose) {
481	                std::cout << "    [V11.2] Profile-Modul fp=0x" << std::hex << h.fingerprint() << std::dec
482	                          << " benutzt YCSB-" << static_cast<int>(wl_it->second) << "\n";
483	            }
484	        }
485	
486	        comdare_measurement_record_v1 rec{};
487	        m->run_workload(inst, wl_for_this_module, &rec);
488	
489	        // Phase 7 TEARDOWN (per-Modul-Instance)
490	        m->destroy_instance(inst);
491	
492	        experiment::PermutationResult pr;
493	        auto                          it = fp_to_id.find(h.fingerprint());
494	        pr.permutation_id = (it != fp_to_id.end()) ? it->second : ("fp_" + std::to_string(h.fingerprint()));
495	        pr.fingerprint    = h.fingerprint();
496	        pr.record         = rec;
497	        pr.succeeded      = true;
498	        // V20.2 — Welchen Workload bekam diese Permutation tatsaechlich?
499	        pr.workload_used = (wl_it != fp_to_workload.end())
500	                               ? workload_to_string(wl_it->second)
501	                               : workload_to_string(wopts.workload); // Default-Workload (Nicht-Profile-Module)
502	        aggregator.add(std::move(pr));
503	        ++total_records;
504	    }
505	
506	    if (opts_.verbose) { std::cout << "[Phase 5+6] Collected " << total_records << " measurement records.\n"; }
507	    return status_ok;
508	}
