522	            std::cout << "[Phase 7] Wrote " << json_path.string() << "\n";
523	        }
524	    } catch (std::exception const& e) {
525	        std::cerr << "[Phase 7] export error: " << e.what() << "\n";
526	        return status_export_failed;
527	    }
528	    return status_ok;
