531	// ─────────────────────────────────────────────────────────────────────────────
532	// Convenience: Full Pipeline (Phase 1-7, mit allen Diagnose-Outputs)
533	// ─────────────────────────────────────────────────────────────────────────────
534	int ExperimentDriver::run_pipeline_full(WorkloadOptions const& wopts) {
535	    // Fix 2026-07-06: ein erfolgreicher Lauf materialisiert IMMER sein deklariertes output_dir —
536	    // auch im enumerate_only-Modus (vorher entstand es erst in phase2_generate; Messreihen-Layout-
537	    // Konsumenten pruefen die Verzeichnis-Existenz je Reihe).
538	    std::error_code output_dir_ec;
539	    std::filesystem::create_directories(opts_.output_dir, output_dir_ec);
540	    if (output_dir_ec) {
541	        std::cerr << "[Pipeline] output_dir nicht anlegbar: " << opts_.output_dir.string() << "\n";
542	        return status_export_failed;
543	    }
544	    std::vector<loop::PermutationDescriptor> descriptors;
545	    int                                      rc = phase1_enumerate(descriptors);
546	    if (rc != status_ok) return rc;
547	
548	    if (opts_.enumerate_only) {
549	        if (opts_.verbose) {
550	            std::cout << "\n[--enumerate-only] Listing all descriptors:\n";
551	            for (auto const& d : descriptors) {
552	                std::cout << "    " << d.id << " (fp=0x" << std::hex << std::setw(16) << std::setfill('0')
553	                          << d.fingerprint << std::dec << ")\n";
554	            }
555	        }
556	        return status_ok;
557	    }
558	
559	    rc = phase2_generate(descriptors);
560	    if (rc != status_ok) return rc;
561	
562	    if (opts_.skip_build) {
563	        if (opts_.verbose) { std::cout << "\n[--skip-build] Generation done, cmake not invoked.\n"; }
564	        return status_ok;
565	    }
566	
567	    rc = phase3_compile();
568	    if (rc != status_ok) return rc;
569	
570	    std::vector<loader::ModuleHandle> handles;
571	    rc = phase4_load(handles);
572	    if (rc != status_ok) return rc;
573	
574	    experiment::ResultAggregator aggregator;
575	    rc = phase5_run_workload(handles, wopts, descriptors, aggregator);
576	    if (rc != status_ok) return rc;
577	
578	    rc = phase7_export(aggregator);
579	    if (rc != status_ok) return rc;
580	
581	    // Module-Handles werden durch RAII (Vector-Destructor) entladen
582	    handles.clear();
583	    if (opts_.verbose) { std::cout << "[Phase 7] Unloaded all modules.\n"; }
584	
585	    return status_ok;
586	}
